  let low = 0, high = m * n - 1;
  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    const val = matrix[Math.floor(mid / n)][mid % n];
    if (val === target) return true;
    if (val < target) low = mid + 1;
    else high = mid - 1;
  }
  return false;
}

